def constructArray(n, k):
    ans = []
    low, high = 1, n

    # Alternate between the smallest and largest available numbers for the first k steps
    for i in range(k):
        if i % 2 == 0:
            ans.append(low)
            low += 1
        else:
            ans.append(high)
            high -= 1

    # Fill the rest: ascending if k is odd (last placed was low - 1),
    # descending if k is even (last placed was high + 1), so the next difference is 1
    if k % 2 == 1:
        while low <= high:
            ans.append(low)
            low += 1
    else:
        while high >= low:
            ans.append(high)
            high -= 1

    return ans
